package com.decimal128.textcodec

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertNull

/**
 * Parse vectors for [Decimal128TextCodec.dpd128Parse], and the NaN payload
 * cases that separate the two formats.
 *
 * A NaN payload is a coefficient, so it is declet-encoded in DPD exactly as a
 * finite coefficient is. Payloads below 10 happen to coincide with BID; from
 * two digits up they diverge. Every expected pairing comes from the shared
 * `string_bid_dpd` corpus, generated by the decimal128-c engine.
 */
class TestDpd128Parse {

    data class TC(val expectedHex: String, val str: String)

    val tcs = arrayOf(
// === Finite: the same grammar and rounding as BID, a different encoding ===
        TC("[2208000000000000,0000000000000000]", "0"),
        TC("[A208000000000000,0000000000000000]", "-0"),
        TC("[2208000000000000,0000000000000001]", "1"),
        TC("[A208000000000000,0000000000000001]", "-1"),
        TC("[2208000000000000,0000000000000009]", "9"),
        TC("[6E080FF3FCFF3FCF,F3FCFF3FCFF3FCFF]", "9999999999999999999999999999999999"),
        TC("[0000000000000000,0000000000000009]", "9E-6176"),

// === Infinity: no coefficient, so byte-identical to BID ===
        TC("[7800000000000000,0000000000000000]", "Infinity"),
        TC("[F800000000000000,0000000000000000]", "-Infinity"),

// === NaN payloads: coincide with BID below 10, diverge from two digits up ===
        TC("[7C00000000000000,0000000000000000]", "NaN"),
        TC("[7C00000000000000,0000000000000001]", "NaN1"),
        TC("[7C00000000000000,0000000000000010]", "NaN10"),
        TC("[7C00000000000000,0000000000000081]", "NaN101"),
        TC("[FE00000000000000,00000000534B9C1E]", "-sNaN1234567890"),
        TC("[7C00000000000000,0BDA60F498388E4E]", "NaN576460752303423488"),
        TC("[7C00000000000000,1000000000000000]", "NaN1000000000000000000"),
        TC("[7C000928CF8BFD99,413B2DCB4DF63344]", "NaN112433781776314088827827199902644"),
        TC("[7E000000000152A2,BCADC0B0E5E29592]", "sNaN1284483683340543498125312"),
        TC("[FE00000340C8971F,13CBA29DF88620BE]", "-sNaN150148854371172722477708308918"),
        TC("[FC0000000001422A,D0FF14CA4F4E18F6]", "-NaN1208925819614629174706176"),
    )

    @Test
    fun testCases() {
        for (tc in tcs) {
            val out = LongArray(2)
            val err = Decimal128TextCodec.dpd128Parse(out, tc.str)
            assertNull(err, "unexpected error for ${tc.str}: $err")
            val hex = "[${hex16(out[0])},${hex16(out[1])}]"
            assertEquals(tc.expectedHex.uppercase(), hex, "for ${tc.str}")
        }
    }

    /** Every vector must round-trip: parse then render returns the input. */
    @Test
    fun roundTrip() {
        for (tc in tcs) {
            val out = LongArray(2)
            assertNull(Decimal128TextCodec.dpd128Parse(out, tc.str))
            assertEquals(tc.str, Decimal128TextCodec.dpd128ToString(out[0], out[1]))
        }
    }

    /** Failures behave as they do for BID, and yield the canonical quiet NaN. */
    @Test
    fun failuresMatchBid() {
        for (bad in arrayOf("", "abc", "1.2.3", "1E", "1E+", "1_", "_1", "NaNx", ".")) {
            val d = LongArray(2)
            val b = LongArray(2)
            val dErr = Decimal128TextCodec.dpd128Parse(d, bad)
            val bErr = Decimal128TextCodec.bid128Parse(b, bad)
            assertNotNull(dErr, "expected failure for <$bad>")
            assertEquals(bErr, dErr, "the formats must reject <$bad> the same way")
            assertEquals(0x7C00000000000000L, d[0])
            assertEquals(0x0000000000000000L, d[1])
        }
    }

    private fun hex16(v: Long): String =
        v.toULong().toString(16).padStart(16, '0').uppercase()
}
